#include <cstdio>
#include <algorithm>
#include <sstream>
#include <vector>
using namespace std;

#define MAX 1000000

int n;
pair<int, int> T[MAX];

int main() {
    int id;
    while (scanf("%d", &n) && n) {
        for (int i = 0; i < n; i++) {
            scanf("%d", &id);
            char line[100]; // Buffer for reading the line
            scanf(" %[^\n]", line); // Read the entire line
            istringstream iss(line);
            int m, s, sum = 0;
            for (int j = 0; j < 4; j++) {
                iss >> m >> s; // Read m and s from the line
                sum += m * 60 + s;
            }
            T[i] = make_pair(sum, id);
        }
        sort(T, T + n);
        printf("%d\n", T[0].second);
        printf("%d\n", T[1].second);
        printf("%d\n", T[n - 2].second);
    }
}

